import { createResource } from "solid-js";

export function asyncLoad(url: string): Promise<string> {
	const request = new XMLHttpRequest();
	const promise = new Promise<string>(function (resolve, reject) {
		request.onload = () => {
			if (request.status == 0 || request.status == 200) {
				resolve(request.responseText);
			} else {
				reject(`${url} - ${request.statusText}`);
			}
		};
		request.onerror = () => reject(`${url} - ${request.statusText}`);
		request.onabort = () => reject(`${url} - Aborted`);
	});
	request.open("GET", url);
	request.send();
	return promise;
}

/**
 * Generates a solid resource for an asynchronously loaded JSON file
 * @param filename The JSON file to load
 * @returns A resource containing the json when loaded
 */
export function createJsonResource<T>(filename: string) {
	return createResource<T>(async () => {
		const response = await asyncLoad(filename);
		return JSON.parse(response) as T;
	});
}
